def photo(key, alt, cls='', w=950):
    return f'<img class="{cls}" src="https://images.unsplash.com/{P[key]}?auto=format&amp;fit=crop&amp;w={w}&amp;q=82" alt="{escape(alt)}" data-fallback loading="lazy" decoding="async">'
def btn(label='Plan your journey',cls='button'):
    return f'<a class="{cls}" href="{FORM}" target="_blank" rel="noopener noreferrer">{label} <span class="arrow" aria-hidden="true">↗</span></a>'
def heading(kicker,title,desc='',center=False):
    return f'<div class="heading {"heading--center" if center else ""} reveal"><span class="eyebrow">{kicker}</span><h2>{title}</h2><p>{desc}</p></div>'
def dest(name,region,desc,pic,tags):
    return f'<article class="dest-card reveal" data-card data-category="{tags}" data-search="{escape(name+" "+region+" "+desc)}">{photo(pic,"Landscape and travel inspiration: "+name,"dest-card__image")}<div class="dest-card__content"><div class="dest-card__meta">{region}</div><h3>{name}</h3><p class="dest-card__text">{desc}</p><a class="dest-card__link" target="_blank" rel="noopener noreferrer" href="{FORM}">Enquire about this destination ↗</a></div></article>'
def service(icon,title,desc,url='services.html'):
    return f'<article class="service-card reveal"><div class="service-card__icon" aria-hidden="true">{icon}</div><h3>{title}</h3><p>{desc}</p><a class="text-link" href="{url}">Learn more ↗</a></article>'
def experience(label,title,desc,pic,tag):
    return f'<article class="experience-card reveal" data-card data-category="{tag}">{photo(pic,title)}<div class="experience-card__inner"><span class="experience-card__label">{label}</span><h3>{title}</h3><p>{desc}</p><a class="text-link" href="{FORM}" target="_blank" rel="noopener noreferrer">Make an enquiry ↗</a></div></article>'
def banner(name,title,desc):
    return f'<section class="banner"><div class="banner__photo" aria-hidden="true"></div><div class="container banner__inner"><div class="breadcrumbs"><a href="index.html">Home</a><span>/</span><span aria-current="page">{name}</span></div><h1>{title}</h1><p>{desc}</p></div></section>'
def header(page):
    menu=''.join('<a href="'+f+'"'+(' aria-current="page"' if page==f else '')+'>'+t+'</a>' for t,f in [('About','about.html'),('Services','services.html'),('Destinations','destinations.html'),('Experiences','experiences.html'),('Contact','contact.html')])
    brand='<a href="index.html" class="brand" aria-label="Prism Travels homepage"><img class="brand__mark" src="assets/prism-symbol.png" width="53" height="62" alt=""><span class="brand__text"><span class="brand__name">PRISM</span><span class="brand__sub">TRAVELS &amp; ADVISORY</span></span></a>'
    return f'<a class="skip-link" href="#main">Skip to main content</a><div class="topbar"><div class="container topbar__inner"><span>PERSONAL TRAVEL PLANNING · INDIA &amp; BEYOND</span><span class="topbar__right">Each Mile With A Smile</span></div></div><header class="site-header"><div class="container header__inner">{brand}<button class="menu-toggle" data-menu-toggle type="button" aria-label="Open menu" aria-expanded="false" aria-controls="main-navigation"><span class="menu-toggle__line" aria-hidden="true"></span></button><nav class="main-nav" id="main-navigation" data-main-nav aria-label="Main navigation">{menu}{btn("Plan My Trip","button nav-cta")}</nav></div></header>'
def footer():
    return f'''<section class="split-band"><div class="container split-band__inner"><div><span class="eyebrow eyebrow--light">YOUR NEXT JOURNEY</span><h2>Ready when you are.</h2><p>Bring us your ideas, your dates, or simply your wish to get away. We'll take the conversation from there.</p></div><div class="split-band__action">{btn('Start a conversation','button button--light')}</div></div></section>
<footer class="site-footer"><div class="container"><div class="footer-grid"><div><a href="index.html" class="brand"><img class="brand__mark" src="assets/prism-symbol.png" alt="" width="53" height="62"><span class="brand__text"><span class="brand__name">PRISM</span><span class="brand__sub">TRAVELS &amp; ADVISORY</span></span></a><p class="footer-intro">Flights, stays, holidays, corporate travel and everything in between — coordinated with a personal touch.</p><div class="footer-tagline">Each Mile With A Smile.</div></div>
<div><div class="footer-title">Explore</div><ul class="footer-links"><li><a href="index.html">Home</a></li><li><a href="about.html">Our story</a></li><li><a href="destinations.html">Destinations</a></li><li><a href="experiences.html">Experiences</a></li></ul></div>
<div><div class="footer-title">Services</div><ul class="footer-links"><li><a href="services.html#flights">Flights &amp; hotels</a></li><li><a href="services.html#holidays">Personal holidays</a></li><li><a href="services.html#corporate">Corporate travel</a></li><li><a href="services.html#events">Groups &amp; events</a></li></ul></div>
<div><div class="footer-title">Talk To Prism</div><p class="footer-news">Prefer a human conversation to a booking algorithm? So do we. Tell us what you are planning.</p>{btn('Enquire now','button button--ghost')}<ul class="footer-links" style="margin-top:22px"><li><a href="contact.html">How enquiries work</a></li><li><a href="privacy.html">Privacy notice</a></li><li><a href="terms.html">Website terms</a></li></ul></div></div><div class="footer-bottom"><span>© <span data-year>2026</span> Prism Travels. All rights reserved.</span><span>Built for considered travel. <a href="privacy.html">Privacy</a> · <a href="terms.html">Terms</a></span></div></div></footer>
<a class="button floating-enquire" href="{FORM}" target="_blank" rel="noopener noreferrer">Enquire ↗</a><button class="back-to-top" type="button" data-back-to-top aria-label="Back to top">↑</button>'''
def write(filename,title,desc,content):
    tit=escape(title+' | Prism Travels',quote=True); description=escape(desc,quote=True)
    s=f'''<!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#071c38"><meta name="description" content="{description}"><meta property="og:type" content="website"><meta property="og:title" content="{tit}"><meta property="og:description" content="{description}"><meta name="referrer" content="strict-origin-when-cross-origin"><title>{tit}</title><link rel="icon" type="image/png" href="assets/favicon.png"><link rel="apple-touch-icon" href="assets/favicon.png"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Manrope:wght@400;500;600;700;800&amp;display=swap" rel="stylesheet"><link href="css/styles.css" rel="stylesheet"><script src="js/site.js" defer></script></head><body>{header(filename)}<main id="main">{content}</main>{footer()}</body></html>'''
    (R/filename).write_text(s,encoding='utf-8')
